import java.util.*;
import java.io.*;

public class Main {
    static final int SIZE = (1 << 21) + 1;
    static final int N = 250005;
    static final int K = 19;
    static int[][] f = new int[N][K];
    static int[] factorials = new int[N];
    static int[] invFactorials = new int[N];
    static int n, k, M;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        M = Integer.parseInt(st.readLine());

        for (int i = 0; i < N; i++) {
            Arrays.fill(f[i], -1);
        }

        prepareFactorials(n);

        if ((n & 1) == 1) {
            System.out.println(power(k, n));
            return;
        }

        int res = sub(power(k, n), mul(factorials[n], recurseDP(n, 0)));
        System.out.println(res);
    }

    static void prepareFactorials(int n) {
        factorials[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorials[i] = mul(factorials[i - 1], i);
        }
        invFactorials[n] = inv(factorials[n]);
        for (int i = n - 1; i >= 0; i--) {
            invFactorials[i] = mul(invFactorials[i + 1], i + 1);
        }
    }

    static int recurseDP(int s, int c) {
        if (s == 0) return 1;
        if (c == k) return 0;
        int res = f[s][c];
        if (res != -1) return res;
        res = 0;
        int hb = 1;
        while (hb <= s) hb <<= 1;
        hb >>= 1;
        for (int t = s; t != -1; t = (t - 1) & s) {
            if ((t & hb) == 0) break;
            res = add(res, mul(invFactorials[t], k - c, recurseDP(s ^ t, c + 1)));
        }
        f[s][c] = res;
        return res;
    }

    static int add(int x, int y) {
        int res = x + y;
        if (res >= M) res -= M;
        return res;
    }

    static int sub(int x, int y) {
        int res = x - y;
        if (res < 0) res += M;
        return res;
    }

    static int mul(int x, int y) {
        return (int)((long) x * y % M);
    }

    static int power(int x, int y) {
        int res = 1;
        int base = x;
        int exp = y;
        while (exp > 0) {
            if ((exp & 1) == 1) res = mul(res, base);
            base = mul(base, base);
            exp >>= 1;
        }
        return res;
    }

    static int inv(int x) {
        return power(x, M - 2);
    }
}
